import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  frame,
} from './neon.js';

// Mock canvas context
const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: '',
  fillText: () => {},
};

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- ISSUE #1: Brick Bounces ---

test('brick hit: top face bounce', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball coming from above, hitting the top edge
  state.ball = { x: 150, y: 100 - 7, r: 7, vx: 0, vy: 200 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), UP, 'Should bounce up');
  assert.ok(state.ball.y <= 100 - 7, 'Should be pushed out of the brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('brick hit: bottom face bounce', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball coming from below, hitting the bottom edge
  state.ball = { x: 150, y: 100 + 20 + 7, r: 7, vx: 0, vy: -200 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), DOWN, 'Should bounce down');
  assert.ok(state.ball.y >= 100 + 20 + 7, 'Should be pushed out of the brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('brick hit: left face bounce', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball coming from the left, hitting the left edge
  state.ball = { x: 100 - 7, y: 110, r: 7, vx: 200, vy: 0 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT, 'Should bounce left');
  assert.ok(state.ball.x <= 100 - 7, 'Should be pushed out of the brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('brick hit: right face bounce', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball coming from the right, hitting the right edge
  state.ball = { x: 100 + 100 + 7, y: 110, r: 7, vx: -200, vy: 0 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), RIGHT, 'Should bounce right');
  assert.ok(state.ball.x >= 100 + 100 + 7, 'Should be pushed out of the brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('brick hit: corner bounce', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball hitting the top-left corner diagonally
  state.ball = { x: 100 - 5, y: 100 - 5, r: 7, vx: 200, vy: 200 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.equal(brick.alive, false);
});

test('brick hit: tunneling prevention (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  // Ball speed at level 6 is 710 px/s. dt = 50ms -> 35.5px.
  // Ball is at y = 90, r = 7. Next pos y = 90 + 35.5 = 125.5.
  // Brick is at y = 100, h = 20. 
  // The ball jumps from 90 to 125.5, skipping the brick entirely if discrete.
  state.ball = { x: 150, y: 90, r: 7, vx: 0, vy: 710 };

  // We need to simulate the a frame where tunneling might occur.
  // Since collision is currently in frame(), and frame doesn't take dt, 
  // we have to check if we can detect it. 
  // Actually, the current implementation of frame() uses the ball's current position.
  // The issue says "Sweep between the two positions". 
  // This means we might need to move collision logic to step() or add a sweep in frame().

  // For now, let's see if a "fast" ball that would have skipped the brick is caught.
  // In the current code, if we just call frame(), it only checks collides(ball, brick).
  // If ball.y was 90 and then became 125.5, collides(ball, brick) is false at both points.

  // We will test if a ball with a very large velocity but starting just before the brick is caught.
  // But this test is for the "Symptom" and "Expected" from ISSUE.md.

  // Let's simulate a jump.
  const dt = 0.05; 
  const oldY = state.ball.y;
  step(state, dt); // Ball moves to 90 + 710 * 0.05 = 125.5

  // Now we call frame. If it's discrete, it won't hit.
  frame(mockCtx, state);

  // If tunneling is fixed, it should have hit the brick.
  assert.equal(brick.alive, false, 'Ball should not tunnel through the brick');
});

