export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks collision & bounce (fixed #1, moved from frame to solve tunneling and logic entanglement)
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Sweep check for tunneling: check if ball was before brick and now is after/inside
    const wasOutside = (oldX + ball.r < brick.x || oldX - ball.r > brick.x + brick.w ||
                        oldY + ball.r < brick.y || oldY - ball.r > brick.y + brick.h);

    if (collides(ball, brick)) {
      // Determine which face was hit based on the smaller penetration
      const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

      if (overlapX < overlapY) {
        // Side hit
        ball.vx = -ball.vx;
        if (ball.x + ball.r / 2 < brick.x + brick.w / 2) {
          ball.x = brick.x - ball.r; // Push out left
        } else {
          ball.x = brick.x + brick.w + ball.r; // Push out right
        }
      } else if (overlapY < overlapX) {
        // Top/Bottom hit
        ball.vy = -ball.vy;
        if (ball.y + ball.r / 2 < brick.y + brick.h / 2) {
          ball.y = brick.y - ball.r; // Push out top
        } else {
          ball.y = brick.y + brick.h + ball.r; // Push out bottom
        }
      } else {
        // Corner hit (equal penetration)
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
        // Push out diagonally based on center position
        if (ball.x + ball.r / 2 < brick.x + brick.w / 2) ball.x = brick.x - ball.r; 
        else ball.x = brick.x + brick.w + ball.r;
        if (ball.y + ball.r / 2 < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
        else ball.y = brick.y + brick.h + ball.r;
      }

      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // To prevent multiple bricks being hit in one frame (since they are close), 
      // we could break here, but usually we want to allow the ball to proceed 
      // if it's moving fast. However, for a "perfect arcade" feel, 
      // one hit per frame is usually safer.
      break; 
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

