    const wasAbove = oldY + ball.r < brick.y;
    const isBelow = ball.y - ball.r > brick.y + brick.h;
    const wasBelow = oldY - ball.r > brick.y + brick.h;
    const isAbove = ball.y + ball.r < brick.y;
    const wasLeft = oldX + ball.r < brick.x;
    const isRight = ball.x - ball.r > brick.x + brick.w;
    const wasRight = oldX - ball.r > brick.x + brick.w;
    const isLeft = ball.x + ball.r < brick.x;

    const tunneledY = (wasAbove && isBelow) || (wasBelow && isAbove);
